const body = $json.body || $json;
return {
  json: {
    caption: String(body.caption || ''),
    video_url: String(body.video_url || ''),
    test_id: String(body.test_id || ''),
    approved_via: String(body.approved_via || $json.approved_via || ''),
    arm_live_publish: body.arm_live_publish === true || String(body.arm_live_publish || '').toLowerCase() === 'true',
    dry_run: body.dry_run === true || String(body.dry_run || '').toLowerCase() === 'true',
    test_mode: body.test_mode === true || String(body.test_mode || '').toLowerCase() === 'true',
    diagnostic: body.diagnostic === true || String(body.diagnostic || '').toLowerCase() === 'true',
  }
};

const store = $getWorkflowStaticData('global');

store.publish_enabled = store.publish_enabled ?? false;
store.allow_one_live_publish = store.allow_one_live_publish ?? false;
store.daily_publish_limit = Number(store.daily_publish_limit ?? 3); // set 2 or 3 as needed
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];

const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;

// Keep a compact rolling window to avoid unbounded growth.
store.daily_publish_success_log = store.daily_publish_success_log.slice(-200);

const todaySuccessCount = store.daily_publish_success_log.filter((r) => String(r.dateKey || '') === todayKey).length;
const dailyLimit = Number($json.daily_publish_limit || store.daily_publish_limit || 3);
const dailyLimitReached = todaySuccessCount >= dailyLimit;

const requestedByApproval =
  $json.arm_live_publish === true ||
  String($json.arm_live_publish || '').toLowerCase() === 'true' ||
  String($json.approved_via || '') === 'telegram_callback';

if (requestedByApproval) {
  store.publish_enabled = true;
  store.allow_one_live_publish = true;
}

const publishEnabled = store.publish_enabled === true || String(store.publish_enabled).toLowerCase() === 'true';
const armEnabled = store.allow_one_live_publish === true || String(store.allow_one_live_publish).toLowerCase() === 'true';
let livePublishAllowed = publishEnabled && armEnabled && !dailyLimitReached;
const inlineDryRun = $json.dry_run === true || $json.test_mode === true || $json.diagnostic === true;
if (inlineDryRun) { livePublishAllowed = false; }

if (livePublishAllowed) {
  // one-shot safety: consume gate immediately for this approved request
  store.publish_enabled = false;
  store.allow_one_live_publish = false;
} else if (publishEnabled && armEnabled && dailyLimitReached) {
  // consume armed gate when blocked by daily cap to prevent accidental carry-over
  store.publish_enabled = false;
  store.allow_one_live_publish = false;
}

let dryRunReason = '';
if (!livePublishAllowed) {
  if (dailyLimitReached) dryRunReason = 'DAILY_LIMIT_REACHED';
  else if (inlineDryRun) dryRunReason = 'inline_test_mode_flag';
  else dryRunReason = publishEnabled ? 'allow_one_live_publish=false' : 'publish_enabled=false';
}

return {
  json: {
    ...$json,
    publish_enabled: publishEnabled,
    allow_one_live_publish: armEnabled,
    live_publish_allowed: livePublishAllowed ? 'true' : 'false',
    daily_publish_limit: dailyLimit,
    daily_publish_count_today: todaySuccessCount,
    daily_publish_date_key: todayKey,
    daily_limit_reached: dailyLimitReached,
    dry_run_reason: livePublishAllowed ? '' : dryRunReason,
    ready_for_live_publish: !livePublishAllowed
  }
};

return {
  json: {
    ...$json,
    dry_run: true,
    publish_attempted: false,
    publish_status: ($json.dry_run_reason === 'DAILY_LIMIT_REACHED') ? 'blocked_daily_limit' : 'blocked_dry_run',
    dry_run_reason: $json.dry_run_reason || 'publish_enabled=false',
    daily_publish_limit: $json.daily_publish_limit ?? null,
    daily_publish_count_today: $json.daily_publish_count_today ?? null,
    next_action: ($json.dry_run_reason === 'DAILY_LIMIT_REACHED')
      ? 'wait until next day or increase daily_publish_limit (2/3)'
      : 'set publish_enabled=true and allow_one_live_publish=true for one live attempt'
  }
};

const store = $getWorkflowStaticData('global');
store.publisher_input_by_exec = store.publisher_input_by_exec || {};
store.publisher_create_by_exec = store.publisher_create_by_exec || {};
const execKey = String($execution.id);
const traced = store.publisher_input_by_exec[execKey] || {};

const stripSensitive = (obj) => {
  if (obj === null || obj === undefined) return obj;
  if (Array.isArray(obj)) return obj.map(stripSensitive);
  if (typeof obj !== 'object') return obj;

  // Before logging any API response:
  const safeResponse = Object.fromEntries(
    Object.entries(obj).filter(([k]) =>
      !/(token|secret|key|credential)/i.test(k)
    )
  );

  return Object.fromEntries(
    Object.entries(safeResponse).map(([k, v]) => [k, stripSensitive(v)])
  );
};

const rawCreateResponse = ($json && typeof $json === 'object') ? $json : {};
const safeCreateResponse = stripSensitive(rawCreateResponse);
const createStatusCode = Number(safeCreateResponse.statusCode || safeCreateResponse.status || 0) || null;
const createBodyRaw = (safeCreateResponse.body && typeof safeCreateResponse.body === 'object')
  ? safeCreateResponse.body
  : safeCreateResponse;
const createBody = stripSensitive(createBodyRaw);

const creationId = String(createBody.id || createBody.creation_id || safeCreateResponse.id || '').trim();
const createErrorObj = (createBody.error && typeof createBody.error === 'object') ? createBody.error : null;
const createErrorMessage = String(
  (createErrorObj && (createErrorObj.message || createErrorObj.error_user_msg || createErrorObj.error_subcode || '')) ||
  createBody.error_message ||
  createBody.message ||
  ''
).trim();
const createErrorCode = String(
  (createErrorObj && (createErrorObj.code || createErrorObj.error_subcode || '')) ||
  createBody.error_code ||
  ''
).trim();

const requestPayload = {
  media_type: 'REELS',
  video_url: String(traced.video_url || ''),
  caption: String(traced.caption || ''),
  endpoint: 'https://graph.facebook.com/v23.0/17841436538210981/media'
};

const responsePayload = {
  statusCode: createStatusCode,
  body: createBody
};

if (!creationId) {
  throw new Error(
    `IG create container failed before readiness: ${createErrorMessage || 'missing creation id'}; statusCode=${createStatusCode || 'NONE'}; video_url=${requestPayload.video_url}; response=${JSON.stringify(responsePayload)}`
  );
}

store.publisher_create_by_exec[execKey] = {
  creation_id: creationId,
  video_url: String(traced.video_url || ''),
  request: requestPayload,
  response: responsePayload,
  response_status_code: createStatusCode,
  response_error_code: createErrorCode,
  response_error_message: createErrorMessage
};

return {
  json: {
    ...$json,
    publisher_input_video_url: String(traced.video_url || ''),
    publisher_input_caption: String(traced.caption || ''),
    publisher_input_source_node: String(traced.source_node || ''),
    publisher_input_is_public_url: traced.is_public_url === true,
    publisher_input_url_host: String(traced.url_host || ''),
    publisher_video_head_status_code: traced.head_status_code ?? null,
    publisher_video_head_content_type: String(traced.head_content_type || ''),
    publisher_video_head_content_length: String(traced.head_content_length || ''),
    publisher_video_head_response: traced.head_response || null,
    publisher_video_head_error: String(traced.head_error || ''),
    creation_id: creationId,
    readiness_check_count: 0,
    readiness_max_checks: 6,
    readiness_interval_seconds: 30,
    ig_create_container_request: requestPayload,
    ig_create_container_response: responsePayload,
    ig_create_container_creation_id: creationId,
    ig_create_container_status_code: createStatusCode,
    ig_create_container_error_code: createErrorCode,
    ig_create_container_error_message: createErrorMessage
  }
};

const store = $getWorkflowStaticData('global');
store.readiness_attempts = store.readiness_attempts || {};
store.readiness_details = store.readiness_details || {};
store.publisher_create_by_exec = store.publisher_create_by_exec || {};

const stripSensitive = (obj) => {
  if (obj === null || obj === undefined) return obj;
  if (Array.isArray(obj)) return obj.map(stripSensitive);
  if (typeof obj !== 'object') return obj;

  // Before logging any API response:
  const safeResponse = Object.fromEntries(
    Object.entries(obj).filter(([k]) =>
      !/(token|secret|key|credential)/i.test(k)
    )
  );

  return Object.fromEntries(
    Object.entries(safeResponse).map(([k, v]) => [k, stripSensitive(v)])
  );
};

const execKey = String($execution.id);
const createCtx = store.publisher_create_by_exec[execKey] || {};

const rawStatusResponse = ($json && typeof $json === 'object') ? $json : {};
const safeStatusResponse = stripSensitive(rawStatusResponse);
const pollHttpStatus = Number(safeStatusResponse.statusCode || safeStatusResponse.status || 0) || null;
const statusBodyRaw = (safeStatusResponse.body && typeof safeStatusResponse.body === 'object')
  ? safeStatusResponse.body
  : safeStatusResponse;
const statusBody = stripSensitive(statusBodyRaw);

const creationId = String(
  statusBody.id ||
  $json.creation_id ||
  safeStatusResponse.id ||
  createCtx.creation_id ||
  ''
).trim();
if (!creationId) {
  throw new Error('Missing creation_id during readiness evaluation');
}

const maxChecks = Number($json.readiness_max_checks || 6);
const prevCount = Number(store.readiness_attempts[creationId] || 0);
const nextCount = prevCount + 1;
store.readiness_attempts[creationId] = nextCount;

const igStatusResponse = {
  statusCode: pollHttpStatus,
  body: statusBody
};
const igStatusCode = String(statusBody.status_code || '').trim().toUpperCase();
const igStatusValue = String(statusBody.status || '').trim();

const igStatusErrorObject = (statusBody.error && typeof statusBody.error === 'object') ? statusBody.error : null;
let igStatusErrorMessageDerived = '';
if (igStatusErrorObject && igStatusErrorObject.message) {
  igStatusErrorMessageDerived = String(igStatusErrorObject.message);
} else if (typeof statusBody.error_message === 'string' && statusBody.error_message.trim()) {
  igStatusErrorMessageDerived = String(statusBody.error_message).trim();
} else if (typeof statusBody.message === 'string' && statusBody.message.trim()) {
  igStatusErrorMessageDerived = String(statusBody.message).trim();
}

const igStatusErrorCode = String(
  (igStatusErrorObject && (igStatusErrorObject.code || igStatusErrorObject.error_subcode || '')) ||
  statusBody.error_code ||
  ''
).trim();

const detail = store.readiness_details[creationId] || {
  checks: [],
  video_url: String($json.publisher_input_video_url || createCtx.video_url || $json.video_url || ''),
  create_response: $json.ig_create_container_response || createCtx.response || null
};

detail.checks.push({
  check_count: nextCount,
  creation_id: creationId,
  poll_http_status: pollHttpStatus,
  ig_status_code: igStatusCode || 'UNKNOWN',
  ig_status_value: igStatusValue || '',
  ig_status_response: igStatusResponse,
  ig_status_error_object: igStatusErrorObject,
  ig_status_error_code: igStatusErrorCode || '',
  ig_status_error_message_derived: igStatusErrorMessageDerived || ''
});

store.readiness_details[creationId] = detail;

const ready = igStatusCode === 'FINISHED';
const hasRealApiError = Boolean(igStatusErrorObject || igStatusErrorMessageDerived);
const canRetry = !ready && !hasRealApiError && nextCount < maxChecks;

const finalStatus = igStatusCode || (hasRealApiError ? 'ERROR' : 'UNKNOWN');
const checks = detail.checks;

if (ready || !canRetry) {
  delete store.readiness_attempts[creationId];
}
if (ready) {
  delete store.readiness_details[creationId];
  delete store.publisher_create_by_exec[execKey];
}

return {
  json: {
    ...$json,
    creation_id: creationId,
    readiness_check_count: nextCount,
    readiness_max_checks: maxChecks,
    readiness_ready: ready,
    readiness_can_retry: canRetry,
    readiness_status_code: finalStatus,
    readiness_status_text: igStatusValue,
    ig_status_response: igStatusResponse,
    ig_status_code: igStatusCode,
    ig_status_value: igStatusValue,
    ig_status_error_object: igStatusErrorObject,
    ig_status_error_code: igStatusErrorCode,
    ig_status_error_message_derived: igStatusErrorMessageDerived,
    ig_status_checks: checks,
    ig_final_status: finalStatus,
    ig_final_error_message: igStatusErrorMessageDerived || '',
    ig_final_creation_id: creationId,
    ig_final_video_url: detail.video_url || '',
    ig_final_status_payload: igStatusResponse
  }
};

const creationId = String($json.ig_final_creation_id || $json.creation_id || 'UNKNOWN');
const status = String($json.ig_final_status || $json.readiness_status_code || 'UNKNOWN');
const checks = Number($json.readiness_check_count || 0);
const videoUrl = String($json.ig_final_video_url || $json.publisher_input_video_url || $json.video_url || '');
const derivedError = String($json.ig_final_error_message || $json.ig_status_error_message_derived || '');

const finalPayload = $json.ig_final_status_payload || $json.ig_status_response || null;
const statusChecks = Array.isArray($json.ig_status_checks) ? $json.ig_status_checks : [];
const lastCheck = statusChecks.length ? statusChecks[statusChecks.length - 1] : null;

let safeFinalPayload = finalPayload;
let safeLastCheck = lastCheck;

try {
  if (finalPayload !== null && finalPayload !== undefined) {
    JSON.stringify(finalPayload);
  }
} catch (e) {
  safeFinalPayload = 'UNSERIALIZABLE_FINAL_PAYLOAD';
}

try {
  if (lastCheck !== null && lastCheck !== undefined) {
    JSON.stringify(lastCheck);
  }
} catch (e) {
  safeLastCheck = 'UNSERIALIZABLE_LAST_CHECK';
}

const readinessDebug = {
  creation_id: creationId,
  status,
  checks,
  video_url: videoUrl,
  derived_error: derivedError,
  final_payload: safeFinalPayload,
  last_check: safeLastCheck
};

const debugStore = $getWorkflowStaticData('global');
debugStore.readiness_timeout_debug = debugStore.readiness_timeout_debug || {};
debugStore.readiness_timeout_debug[String($execution.id)] = readinessDebug;

throw new Error(`Readiness timeout: creation_id=${creationId} status=${status} checks=${checks} error=${derivedError || 'NONE'}`);

const store = $getWorkflowStaticData("global");

store.publish_enabled = false;
store.allow_one_live_publish = false;
store.daily_publish_limit = Number(store.daily_publish_limit ?? 3);
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];

const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const dateKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;

const first = ($input.first() && $input.first().json) ? $input.first().json : {};
store.daily_publish_success_log.push({
  dateKey,
  timestamp: new Date().toISOString(),
  executionId: String($execution.id),
  test_id: String(first.test_id || ''),
  media_id: String(first.id || first.media_id || '')
});
store.daily_publish_success_log = store.daily_publish_success_log.slice(-200);

return items;

const caption = String($json.caption ?? $json.captionText ?? '');

if (/\?{2,}/.test(caption) || caption.includes('?')) {
  throw new Error('Caption encoding corrupted - publishing blocked');
}

return { json: { ...$json } };

const inputVideoUrl = String($json.video_url || '').trim();
const inputCaption = String($json.caption || '');
const sourceNode = 'Publish Safety Gate';

const stripSensitive = (obj) => {
  if (obj === null || obj === undefined) return obj;
  if (Array.isArray(obj)) return obj.map(stripSensitive);
  if (typeof obj !== 'object') return obj;

  // Before logging any API response:
  const safeResponse = Object.fromEntries(
    Object.entries(obj).filter(([k]) =>
      !/(token|secret|key|credential)/i.test(k)
    )
  );

  return Object.fromEntries(
    Object.entries(safeResponse).map(([k, v]) => [k, stripSensitive(v)])
  );
};

let parsedHost = '';
let isHttp = false;
let hasHost = false;
let isPublicLike = false;
let invalidReason = '';

if (!inputVideoUrl) {
  invalidReason = 'video_url is empty';
} else {
  const m = inputVideoUrl.match(/^https?:\/\/([^\/?#]+)/i);
  if (m && m[1]) {
    parsedHost = String(m[1]).trim().toLowerCase();
    isHttp = true;
    hasHost = parsedHost.length > 0;
    const localhostLike = /^(localhost|127\.|0\.0\.0\.0$|::1$)/i.test(parsedHost);
    isPublicLike = hasHost && !localhostLike;
  } else {
    invalidReason = 'video_url must be absolute http/https URL';
  }
}

const looksSample = /samplelib\.com|gtv-videos-bucket|ForBiggerJoyrides|ForBiggerEscapes/i.test(inputVideoUrl);
const looksMissing = /(^$|undefined|null|replace-me|example\.com)/i.test(inputVideoUrl);

let valid = true;
if (!inputVideoUrl || !isHttp || !hasHost || !isPublicLike || looksSample || looksMissing) {
  valid = false;
}

let reason = 'ok';
if (!valid) {
  if (invalidReason) reason = invalidReason;
  else if (!isHttp) reason = 'video_url must start with http/https';
  else if (!hasHost) reason = 'video_url host missing';
  else if (!isPublicLike) reason = 'video_url does not look publicly reachable';
  else if (looksSample) reason = 'video_url appears to be sample/fallback asset';
  else if (looksMissing) reason = 'video_url appears temporary/invalid placeholder';
  throw new Error(`Publisher video URL preflight failed: ${reason}; url=${inputVideoUrl}`);
}

let headStatusCode = null;
let headContentType = '';
let headContentLength = '';
let headSafeResponse = null;
let headError = '';

try {
  const headRaw = await this.helpers.httpRequest({
    method: 'HEAD',
    url: inputVideoUrl,
    resolveWithFullResponse: true,
    simple: false,
    followRedirect: true,
    timeout: 15000,
  });

  const headSafe = stripSensitive(headRaw);
  const headHeaders = (headSafe && typeof headSafe.headers === 'object') ? headSafe.headers : {};
  headStatusCode = Number(headSafe?.statusCode || headSafe?.status || 0) || null;
  headContentType = String(
    headHeaders['content-type'] ||
    headHeaders['Content-Type'] ||
    ''
  );
  headContentLength = String(
    headHeaders['content-length'] ||
    headHeaders['Content-Length'] ||
    ''
  );
  headSafeResponse = headSafe;
} catch (e) {
  headError = String((e && e.message) || e || '');
  const errResponse = (e && e.response && typeof e.response === 'object') ? e.response : null;
  if (errResponse) {
    const safeErr = stripSensitive(errResponse);
    const h = (safeErr && typeof safeErr.headers === 'object') ? safeErr.headers : {};
    headStatusCode = Number(safeErr?.statusCode || safeErr?.status || 0) || null;
    headContentType = String(h['content-type'] || h['Content-Type'] || '');
    headContentLength = String(h['content-length'] || h['Content-Length'] || '');
    headSafeResponse = safeErr;
  }
}

const captionType = typeof $json.caption;
const captionSample = inputCaption.slice(0, 80);
const captionHasQuestionMarks = /\?{2,}/.test(inputCaption) || inputCaption.includes('?');
const captionHasKorean = /[가-힣]/.test(inputCaption);
const igCreateRequestShape = {
  media_type: 'REELS',
  video_url: inputVideoUrl,
  caption: inputCaption
};

const store = $getWorkflowStaticData('global');
store.publisher_input_by_exec = store.publisher_input_by_exec || {};
store.publisher_input_by_exec[String($execution.id)] = {
  video_url: inputVideoUrl,
  caption: inputCaption,
  source_node: sourceNode,
  is_public_url: isPublicLike,
  url_host: parsedHost,
  test_id: String($json.test_id || ''),
  head_status_code: headStatusCode,
  head_content_type: headContentType,
  head_content_length: headContentLength,
  head_response: headSafeResponse,
  head_error: headError
};

return {
  json: {
    ...$json,
    publisher_input_video_url: inputVideoUrl,
    publisher_input_caption: inputCaption,
    publisher_input_source_node: sourceNode,
    publisher_input_is_public_url: isPublicLike,
    publisher_input_url_host: parsedHost,
    publisher_video_url_valid: valid,
    publisher_video_url_reason: reason,
    publisher_video_head_status_code: headStatusCode,
    publisher_video_head_content_type: headContentType,
    publisher_video_head_content_length: headContentLength,
    publisher_video_head_response: headSafeResponse,
    publisher_video_head_error: headError,
    publisher_caption_raw: inputCaption,
    publisher_caption_type: captionType,
    publisher_caption_sample: captionSample,
    publisher_caption_has_question_marks: captionHasQuestionMarks,
    publisher_caption_has_korean: captionHasKorean,
    publisher_ig_create_request_shape: igCreateRequestShape
  }
};

const creationId = String($json.creation_id || $json.id || '').trim();
const caption = String($json.caption || '').trim();

const creationValid = creationId.length > 0;
const captionValid = true;

const payload = {
  creation_id: creationId,
  access_token: 'REDACTED'
};

let payloadValid = creationValid;
let errorReason = '';

if (!creationValid) {
  payloadValid = false;
  errorReason = 'creation_id is empty';
}

try {
  JSON.stringify(payload);
} catch (e) {
  payloadValid = false;
  errorReason = `payload serialization failed: ${e.message}`;
}

if (!payloadValid) {
  throw new Error(`IG publish payload invalid: ${errorReason}`);
}

return {
  json: {
    ...$json,
    ig_publish_creation_id: creationId,
    ig_publish_caption: caption,
    ig_publish_creation_id_valid: creationValid,
    ig_publish_caption_valid: captionValid,
    ig_publish_payload_valid: payloadValid,
    ig_publish_payload_error_reason: errorReason,
    ig_publish_request_payload: payload,
    ig_publish_request: {
      endpoint: 'https://graph.facebook.com/v23.0/17841436538210981/media_publish',
      contentType: 'form-urlencoded',
      body: payload
    }
  }
};

const body = $json.body || $json;
return {
  json: {
    caption: String(body.caption || ''),
    video_url: String(body.video_url || ''),
    test_id: String(body.test_id || ''),
    approved_via: String(body.approved_via || $json.approved_via || ''),
    arm_live_publish: body.arm_live_publish === true || String(body.arm_live_publish || '').toLowerCase() === 'true',
    dry_run: body.dry_run === true || String(body.dry_run || '').toLowerCase() === 'true',
    test_mode: body.test_mode === true || String(body.test_mode || '').toLowerCase() === 'true',
    diagnostic: body.diagnostic === true || String(body.diagnostic || '').toLowerCase() === 'true',
  }
};

const store = $getWorkflowStaticData('global');

store.publish_enabled = store.publish_enabled ?? false;
store.allow_one_live_publish = store.allow_one_live_publish ?? false;
store.daily_publish_limit = Number(store.daily_publish_limit ?? 3); // set 2 or 3 as needed
store.daily_publish_success_log = Array.isArray(store.daily_publish_success_log) ? store.daily_publish_success_log : [];

const nowSeoul = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const todayKey = `${nowSeoul.getFullYear()}-${String(nowSeoul.getMonth() + 1).padStart(2, '0')}-${String(nowSeoul.getDate()).padStart(2, '0')}`;

// Keep a compact rolling window to avoid unbounded growth.
store.daily_publish_success_log = store.daily_publish_success_log.slice(-200);

const todaySuccessCount = store.daily_publish_success_log.filter((r) => String(r.dateKey || '') === todayKey).length;
const dailyLimit = Number($json.daily_publish_limit || store.daily_publish_limit || 3);
const dailyLimitReached = todaySuccessCount >= dailyLimit;

const requestedByApproval =
  $json.arm_live_publish === true ||
  String($json.arm_live_publish || '').toLowerCase() === 'true' ||
  String($json.approved_via || '') === 'telegram_callback';

if (requestedByApproval) {
  store.publish_enabled = true;
  store.allow_one_live_publish = true;
}

const publishEnabled = store.publish_enabled === true || String(store.publish_enabled).toLowerCase() === 'true';
